package com.gameaggregator.billingservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="usage_records") public class UsageRecord{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String idempotencyKey;@Column(nullable=false)public UUID clientId;@Column(nullable=false)public long quantity;@Column(nullable=false)public Instant occurredAt;protected UsageRecord(){}public UsageRecord(String i,UUID c,long q,Instant o){idempotencyKey=i;clientId=c;quantity=q;occurredAt=o;}}